// Arkon Escalation Record - request validation.
// The escalation is a write, so the contract is checked before the store is even
// read: a malformed request must not consume an escalation id.
const MAX_REASON = 500;
const MIN_REASON = 5;

// Parameters may arrive in the JSON body or in the query string. Both are
// supported for one reason: Langflow's API Request component can hand a model
// the URL and nothing else, so an agent-composed body is not possible. The
// method stays POST, set on the canvas rather than by the model, so the verb
// still says that this call changes something.
const incoming = $input.first().json;
const body = { ...(incoming.query ?? {}), ...(incoming.body ?? {}) };
const errors = [];

const text = (value) => (value === undefined || value === null ? "" : String(value).trim());

let incidentId = text(body.incident_id);
if (!incidentId) {
  errors.push("incident_id is required");
} else {
  const digits = incidentId.replace(/[^0-9]/g, "");
  if (!/^(ARK-INC-)?[0-9]+$/i.test(incidentId) || digits === "") {
    errors.push("incident_id must look like ARK-INC-00014 or be a plain number");
  } else {
    incidentId = "ARK-INC-" + digits.padStart(5, "0");
  }
}

const reason = text(body.reason);
if (reason.length < MIN_REASON) {
  errors.push("reason is required and must be at least " + MIN_REASON + " characters");
} else if (reason.length > MAX_REASON) {
  errors.push("reason must be at most " + MAX_REASON + " characters");
}

const requestedBy = text(body.requested_by) || "arkon-quality-assistant";
const approvedBy = text(body.approved_by) || "human approval gate";

// Test affordance only, and the same one the incident status API carries: it
// lets the assistant's 503 branch be demonstrated on demand without moving the
// store aside. It is read after validation and before anything is opened, so a
// malformed request still gets its 400 and no escalation id is consumed. A
// production deployment removes it or puts it behind an operator role.
const simulateFailure = ["1", "true", "yes"].includes(text(body.simulate_failure).toLowerCase());

return [
  {
    json: {
      valid: errors.length === 0,
      errors,
      simulate_failure: simulateFailure,
      request: {
        incident_id: incidentId,
        reason: reason.slice(0, MAX_REASON),
        requested_by: requestedBy.slice(0, 120),
        approved_by: approvedBy.slice(0, 120),
      },
    },
  },
];

// Arkon Escalation Record - confirm the incident exists, then build the record.
// An escalation against an incident that is not in the store is refused: it would
// be an audit entry pointing at nothing.
//
// The status captured here is the fold of the transition log, not the value on
// the store line. Reading the line directly would write "new" into every
// escalation record for ever, which is a false statement in an audit entry whose
// whole purpose is to say what the incident was doing when somebody escalated it.
const LIFECYCLE = ["new", "acknowledged", "in_containment", "resolved", "closed", "false_positive"];
const OPEN_STATUSES = ["new", "acknowledged", "in_containment"];
const TERMINAL_STATUSES = ["closed", "false_positive"];
const REQUESTABLE_STATUSES = ["acknowledged", "in_containment", "resolved", "closed", "false_positive"];
const ALLOWED_TRANSITIONS = {"new": ["acknowledged", "false_positive"], "acknowledged": ["in_containment", "resolved", "false_positive"], "in_containment": ["resolved", "false_positive"], "resolved": ["closed", "in_containment", "false_positive"], "closed": [], "false_positive": []};
const ACK_WINDOW_MINUTES = {"P1": 15, "P2": 60};
// Apply the transition log to one incident. The incident line in the store is
// written once, at new, and never rewritten; the current status is therefore the
// last transition recorded against it, and the KPI timestamps are the first time
// each milestone was reached. Charter 7.2.
function arkonFold(incident, transitionsById) {
  const list = (transitionsById[incident.incident_id] ?? [])
    .slice()
    .sort((a, b) => String(a.recorded_at ?? "").localeCompare(String(b.recorded_at ?? "")));

  const stored = String(incident.status ?? "new").toLowerCase();
  const current = list.length ? String(list[list.length - 1].to_status).toLowerCase() : stored;

  const firstAt = (status) => {
    const hit = list.find((t) => String(t.to_status).toLowerCase() === status);
    return hit ? hit.recorded_at : null;
  };

  const created = Date.parse(incident.created_at ?? "");
  const minutesFromCreated = (iso) => {
    if (!iso || Number.isNaN(created)) return null;
    const at = Date.parse(iso);
    return Number.isNaN(at) ? null : Math.round(((at - created) / 60000) * 10) / 10;
  };

  const acknowledgedAt = firstAt("acknowledged");
  const resolvedAt = firstAt("resolved");
  // A false_positive is a closing outcome: the incident is finished with, and a
  // response time that counted only "closed" would silently drop those cases.
  const closedAt = firstAt("closed") ?? firstAt("false_positive");

  return {
    status: current,
    stored_status: stored,
    transition_count: list.length,
    is_terminal: TERMINAL_STATUSES.includes(current),
    acknowledged_at: acknowledgedAt,
    resolved_at: resolvedAt,
    closed_at: closedAt,
    minutes_to_acknowledge: minutesFromCreated(acknowledgedAt),
    minutes_to_resolve: minutesFromCreated(resolvedAt),
    minutes_to_close: minutesFromCreated(closedAt),
    history: list.map((t) => ({
      transition_id: t.transition_id ?? null,
      recorded_at: t.recorded_at ?? null,
      from_status: t.from_status ?? null,
      to_status: t.to_status ?? null,
      actor: t.actor ?? null,
      note: t.note ?? null,
    })),
  };
}

// Parse a JSONL store into transitions grouped by incident id. Damaged lines are
// counted rather than thrown: one bad line must not take the whole lifecycle out.
function arkonTransitionsById(text) {
  const byId = {};
  let unreadable = 0;
  for (const line of String(text ?? "").split("\n").map((l) => l.trim()).filter(Boolean)) {
    try {
      const record = JSON.parse(line);
      const id = String(record.incident_id ?? "");
      if (!id) {
        unreadable += 1;
        continue;
      }
      (byId[id] = byId[id] ?? []).push(record);
    } catch (error) {
      unreadable += 1;
    }
  }
  return { byId, unreadable };
}

const request = $("Validate Escalation").first().json.request;
const storeText = $("Extract Store Text").first().json.store_text ?? "";
const transitionsText = $("Extract Transitions Text").first().json.transitions_text ?? "";

const incidents = [];
for (const line of storeText.split("\n").map((l) => l.trim()).filter(Boolean)) {
  try {
    incidents.push(JSON.parse(line));
  } catch (error) {
    // A damaged line is not an escalation failure; the status API reports the count.
  }
}

const incident = incidents.find((item) => item.incident_id === request.incident_id) ?? null;
if (!incident) {
  return [{ json: { found: false, incident_id: request.incident_id } }];
}

// Escalation ids come from workflow static data, the same mechanism the intake
// workflow uses for incident ids. Static data persists for production executions
// of a published workflow, not for editor test runs.
const state = $getWorkflowStaticData("global");
state.nextEscalationId = (state.nextEscalationId ?? 0) + 1;
const escalationId = "ARK-ESC-" + String(state.nextEscalationId).padStart(5, "0");

const lifecycle = arkonFold(incident, arkonTransitionsById(transitionsText).byId);

const record = {
  escalation_id: escalationId,
  created_at: new Date().toISOString(),
  incident_id: incident.incident_id,
  incident_priority: incident.priority,
  incident_status_at_escalation: lifecycle.status,
  incident_transitions_at_escalation: lifecycle.transition_count,
  incident_summary: incident.summary,
  reason: request.reason,
  requested_by: request.requested_by,
  approved_by: request.approved_by,
  notification_channel: "none",
  context_origin: "simulated",
};

return [
  {
    json: {
      found: true,
      escalation: record,
      escalation_jsonl: JSON.stringify(record) + "\n",
    },
  },
];
